uniform sampler2D tGroundNoise;
uniform sampler2D tGroundNearestNoise;
uniform sampler2D tGroundMouse;
uniform vec3 uGroundTransitionColor;
uniform vec3 uGroundLightColor;
uniform vec3 uGroundDarkColor;
uniform vec2 uGroundResolution;
uniform float uGroundTime;
uniform float uGroundPage;
uniform float uGroundTransition;
uniform float uGroundTransitionDirection;
uniform float uGroundChapter;
uniform float uGroundScrollProgress;

varying vec2 vGroundUv;
varying vec3 vGroundWorldPosition;
varying vec3 vGroundNormal;
varying vec3 vGroundViewPosition;

void main() {
  vec2 safeResolution = max(uGroundResolution, vec2(1.0));
  vec2 screenUv = gl_FragCoord.xy / safeResolution;
  vec3 normal = normalize(vGroundNormal);
  vec3 viewDir = normalize(vGroundViewPosition);

  vec2 flowUv = vGroundUv + vec2(0.04 * uGroundScrollProgress, 0.0);
  vec2 worldUv = vGroundWorldPosition.xz * 0.01 + vec2(0.04 * uGroundScrollProgress);
  float noiseA = texture2D(tGroundNoise, flowUv).r;
  float noiseB = texture2D(tGroundNoise, worldUv).g;
  float nearestNoise = texture2D(tGroundNearestNoise, vGroundUv * 10.0).b;
  float mouse = texture2D(tGroundMouse, screenUv).r;

  float bands = 0.5 + 0.5 * sin(vGroundWorldPosition.y * 0.12);
  float rings = 0.5 + 0.5 * sin(length(vGroundWorldPosition.xz) * 0.08);
  float fresnel = pow(1.0 - max(dot(normal, viewDir), 0.0), 2.8);
  float slope = 1.0 - abs(normal.y);
  float pulse = 0.5 + 0.5 * sin(vGroundWorldPosition.x * 0.06);
  float transitionMix = smoothstep(0.0, 0.25, uGroundTransition);
  vec2 smokeUvA = vGroundWorldPosition.xz * 0.0025 + vec2(0.08 * uGroundScrollProgress, 0.0);
  vec2 smokeUvB = vGroundWorldPosition.xz * 0.004 - vec2(0.02 * uGroundScrollProgress, 0.03);
  float smokeBase = texture2D(tGroundNoise, smokeUvA).r;
  float smokeDetail = texture2D(tGroundNoise, smokeUvB).g;
  float smokeShape = smoothstep(0.54, 0.86, smokeBase * 0.75 + smokeDetail * 0.45);
  float smokeHeight = smoothstep(10.0, -4.0, vGroundWorldPosition.y);
  float smokeDistance = smoothstep(35.0, 160.0, length(vGroundWorldPosition.xz));
  float smokeSlope = 1.0 - smoothstep(0.2, 0.75, slope);
  float smokeView = 0.65 + 0.35 * smoothstep(0.0, 0.7, 1.0 - abs(dot(normal, viewDir)));
  float smoke = smokeShape * smokeHeight * smokeDistance * smokeSlope * smokeView;

  vec3 base = mix(uGroundDarkColor * 0.25, uGroundLightColor, bands);
  vec3 accent = mix(uGroundLightColor, uGroundTransitionColor, 0.5 + 0.5 * uGroundTransitionDirection);
  vec3 color = mix(base, accent, 0.35 * rings + 0.25 * noiseA);
  vec3 smokeColor = mix(vec3(0.72, 0.76, 0.79), vec3(0.9, 0.93, 0.95), smokeDetail);

  color += accent * fresnel * 1.6;
  color += uGroundLightColor * pulse * slope * 0.9;
  color += accent * mouse * (1.5 + 0.5 * nearestNoise);
  color = mix(color, smokeColor, 0.1 * smoke);
