export type ObjectId = keyof ObjectOptionsByKey;
export type ObjectTimelineVars = Record<string, unknown>;
export type InitialObjectTimelineState = Partial<
  Record<ObjectId, ObjectTimelineVars>
>;

export type SceneSettings = {
