import * as THREE from "three";
import { SceneObject } from "../../core/SceneObject.js";
import type { SceneObjectContext } from "../../types/engine.types.js";
import type {
  GravityBallsObjectOptions,
  GravityBallsTweenProps,
  SmokeFloorRuntime,
} from "../../types/object.types.js";

interface SphereInfo {
  ID: number;
  startX: number;
  startY: number;
  startZ: number;
  spawnX: number;
  spawnY: number;
  vx: number;
  vy: number;
  vz: number;
  gravity: number;
  rotDir: number;
  shrinkRate: number;
  initScale: number;
  bounced: boolean;
  vxMult: number;
  vzMult: number;
  vyMult: number;
  sphere: THREE.Sprite;
  material: THREE.SpriteMaterial;
}

type ResolvedOpts = {
  attachTo: string;
  spawnOffset: { x?: number; y?: number; z?: number };
  colors: string[];
  dotsPerInterval: number;
  physicsScale: number;
  proximityRange: number;
  maxGravityBoost: number;
  vxMult: number;
  vzMult: number;
  vyMult: number;
};

const FADE_START_SCALE = 0.65;
const SMOKE_Z_DRIFT = 0.002;
const SMOKE_SPREAD = 1.005;
const DEFAULT_PARTICLE_SCALE_MIN = 1.2;
const DEFAULT_PARTICLE_SCALE_MAX = 3.0;
const LIFETIME_TICKS = 150;
const SMOKE_FLOOR_RUNTIME_KEY = "smokeFloor.runtime";

const DEFAULT_TEXTURE_URLS = [
  "/resource/images/texture/smoke/smoke_01.png",
  "/resource/images/texture/rocket/smoke.png",
];

const DEFAULTS = {
  attachTo: "rocket",
  spawnOffset: { x: 0 as number, y: -0.34 as number, z: 0 as number },
  colors: ["#FFFFFF", "#F5F5F5", "#EEEEEE"] as string[],
  dotsPerInterval: 3,
  physicsScale: 0.006,
  proximityRange: 4.0,
  maxGravityBoost: 3.0,
  vxMult: 2.5,
  vzMult: 1.5,
  vyMult: -0.5,
  gravityBase: 10,
  floorLevel: -2.5,
  floorDimensions: 25,
};

export class GravityBalls extends SceneObject<GravityBallsTweenProps> {
  private readonly _balls = new Map<number, SphereInfo>();
  private _idx = 0;
  private _accumMs = 0;
  private readonly _spawnPt = new THREE.Vector3();
  private _opts: GravityBallsObjectOptions = {};
  private _baseMats: THREE.SpriteMaterial[] = [];

  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
    if (props) this._opts = { ...this._opts, ...props };
    return this;
  }

  protected override getOptions(): Record<string, unknown> {
    return this._opts as Record<string, unknown>;
  }

  override async runObject(): Promise<void> {
    const ctx = this._context;
    if (!ctx) return;

    const urls: string[] =
      this._opts.textureUrls?.length ? this._opts.textureUrls
      : this._opts.textureUrl ? [this._opts.textureUrl]
      : DEFAULT_TEXTURE_URLS;

    const textures = await Promise.all(
      urls.map(async (url): Promise<THREE.Texture | null> => {
        if (!url || !ctx.loadTexture) return null;
        try { return await ctx.loadTexture(this.resolveAssetPath(url)); }
        catch { return null; }
      }),
    );

    this._baseMats = textures.length > 0
      ? textures.map(tex => new THREE.SpriteMaterial({
          map: tex ?? null,
          transparent: true,
          depthWrite: false,
          opacity: 0.8,
        }))
      : [new THREE.SpriteMaterial({ transparent: true, depthWrite: false, opacity: 0.8 })];

    this._applyOptionVisibility();
  }

  override runUpdate(delta: number): void {
    const ctx = this._context;
    if (!ctx || this._disposed) return;

    this._accumMs += delta * 1000;
    if (this._accumMs >= 15) {
      this._accumMs -= 15;
      this._tick(ctx);
    }
  }

  private _getFloorRuntime(): SmokeFloorRuntime | null {
    const candidate = this._context?.getObject(SMOKE_FLOOR_RUNTIME_KEY);
    if (candidate && typeof (candidate as unknown as SmokeFloorRuntime).getFloorY === "function") {
      return candidate as unknown as SmokeFloorRuntime;
    }
    return null;
  }

  private _computeGravityScale(rocketY: number, floorY: number, o: ResolvedOpts): number {
    const dist = Math.max(0, rocketY - floorY);
    const t = 1 - Math.min(1, dist / o.proximityRange);
    return 1 + t * o.maxGravityBoost;
  }

  private _tick(ctx: SceneObjectContext): void {
    const o = this._resolve();

    if (o.attachTo) {
      const rkt = ctx.getObject(o.attachTo);
      if (rkt instanceof THREE.Object3D) {
        rkt.getWorldPosition(this._spawnPt);
        this._spawnPt.x += o.spawnOffset.x ?? 0;
        this._spawnPt.y += o.spawnOffset.y ?? 0;
        this._spawnPt.z += o.spawnOffset.z ?? 0;
      }
    }

    const floorRuntime = this._getFloorRuntime();
    const floorY = floorRuntime?.getFloorY() ?? (this._opts.floorLevel ?? DEFAULTS.floorLevel);
    const floorDim = floorRuntime?.getFloorDimensions() ?? (this._opts.floorDimensions ?? DEFAULTS.floorDimensions);
    const gravityScale = this._computeGravityScale(this._spawnPt.y, floorY, o);

    for (let i = 0; i < o.dotsPerInterval; i++) this._spawn(ctx, o, gravityScale);

    const dead: number[] = [];
    this._balls.forEach((b, id) => { if (this._step(b, floorY, floorDim)) dead.push(id); });
    for (const id of dead) this._balls.delete(id);
  }

  private _spawn(ctx: SceneObjectContext, o: ResolvedOpts, gravityScale: number): void {
    if (this._baseMats.length === 0) return;

    const s = o.physicsScale;
    const baseMat = this._baseMats[Math.floor(Math.random() * this._baseMats.length)];
    const mat = baseMat.clone();

    const color = o.colors[this._rnd(0, o.colors.length)] ?? o.colors[0];
    mat.color.set(color);
    mat.rotation = Math.random() * Math.PI * 2;

    const initScale = MIN_INIT_SCALE + Math.random() * (MAX_INIT_SCALE - MIN_INIT_SCALE);
    const shrinkRate = -(initScale - 0.1) / LIFETIME_TICKS;

    const isXNeg = this._rnd(0, 2) === 0;
    const isZNeg = this._rnd(0, 2) === 0;

    const sprite = new THREE.Sprite(mat);
    sprite.scale.setScalar(initScale);

    const info: SphereInfo = {
      ID: ++this._idx,
      startX: this._spawnPt.x,
      startY: this._spawnPt.y,
      startZ: this._spawnPt.z,
      spawnX: this._spawnPt.x,
      spawnY: this._spawnPt.y,
      vx: isXNeg ? this._rnd(0, 50) * -0.15 * s : this._rnd(0, 50) * 0.15 * s,
      vy: this._rnd(-10, 10) * s,
      vz: isZNeg ? this._rnd(1, 26) * -0.4 * s : this._rnd(1, 26) * 0.4 * s,
      gravity: DEFAULTS.gravityBase * s * gravityScale,
      rotDir: (Math.random() < 0.5 ? 1 : -1) * (0.003 + Math.random() * 0.006),
      shrinkRate,
      initScale,
      bounced: false,
      vxMult: o.vxMult,
      vzMult: o.vzMult,
      vyMult: o.vyMult,
      sphere: sprite,
      material: mat,
    };

    ctx.scene.add(sprite);
    this._balls.set(info.ID, info);
  }

  private _step(b: SphereInfo, floorY: number, floorDim: number): boolean {
    const sp = b.sphere;

    sp.scale.x += b.shrinkRate;
    sp.scale.y += b.shrinkRate;

    b.startX += b.vx * 0.6;
    b.startY -= b.vy * 0.5;
    b.startZ -= b.vz * 0.6;
    sp.position.x = b.startX;
    sp.position.y = b.startY;
    sp.position.z = b.startZ;

    b.vy += b.gravity;
    b.material.rotation += b.rotDir;

    const bounceY = floorY + b.initScale * sp.scale.x;
    if (sp.position.y < bounceY) {
      sp.position.y = bounceY;
      b.startY = bounceY;

      const inBounds =
        Math.abs(sp.position.x) < floorDim / 2 &&
        Math.abs(sp.position.z) < floorDim / 2;

      if (!b.bounced) {
        b.vx *= b.vxMult;
        b.vz *= b.vzMult;
        if (inBounds) b.vy *= b.vyMult;
        b.bounced = true;
      } else {
        b.vx *= 0.92;
        b.vz *= 0.92;
        if (inBounds) b.vy *= b.vyMult;
      }
    }

    if (sp.scale.y < FADE_START_SCALE) {
      b.material.opacity = Math.max(0, (sp.scale.y - 0.1) / (FADE_START_SCALE - 0.1));
      sp.position.z -= SMOKE_Z_DRIFT;
      const dx = b.startX - b.spawnX;
      const dy = b.startY - b.spawnY;
      b.startX = b.spawnX + dx * SMOKE_SPREAD;
      b.startY = b.spawnY + dy * SMOKE_SPREAD;
    }

    if (sp.scale.y <= 0.1) {
      this._context?.scene.remove(sp);
      b.material.dispose();
      return true;
    }
    return false;
  }

  protected override applyVisibility(visible: boolean): void {
    this._balls.forEach(b => { b.sphere.visible = visible; });
  }

  override dispose(): void {
    if (this._disposed) return;
    const scene = this._context?.scene;

    this._balls.forEach(b => {
      scene?.remove(b.sphere);
      b.material.dispose();
    });
    this._balls.clear();

    for (const mat of this._baseMats) mat.dispose();
    this._baseMats = [];

    super.dispose();
  }

  private _resolve(): ResolvedOpts {
    const o = this._opts;
    return {
      attachTo: o.attachTo ?? DEFAULTS.attachTo,
      spawnOffset: o.spawnOffset ?? DEFAULTS.spawnOffset,
      colors: (o.colors && o.colors.length > 0) ? o.colors : DEFAULTS.colors,
      dotsPerInterval: o.dotsPerInterval ?? DEFAULTS.dotsPerInterval,
      physicsScale: o.physicsScale ?? DEFAULTS.physicsScale,
      proximityRange: o.proximityRange ?? DEFAULTS.proximityRange,
      maxGravityBoost: o.maxGravityBoost ?? DEFAULTS.maxGravityBoost,
      vxMult: o.vxMult ?? DEFAULTS.vxMult,
      vzMult: o.vzMult ?? DEFAULTS.vzMult,
      vyMult: o.vyMult ?? DEFAULTS.vyMult,
    };
  }

  private _rnd(min: number, max: number): number {
    return Math.floor(Math.random() * (max - min)) + min;
  }
}

import * as THREE from "three";
import {
  aboutLights as aboutLightsId,
  earth as earthId,
  jetEngine as jetEngineId,
  rocket as rocketId,
  terrian as terrianId,
} from "../../../core/setup.js";
import type { SceneObject } from "../../../core/SceneObject.js";
import type { Engine } from "../../../core/Engine.js";
import type { SceneFromState } from "../../../types/core.types.js";
import type {
  ContactCameraTheatreValue,
  ContactLightsPort,
  ContactSceneState,
  ContactTransformState,
} from "../../../types/contact.types.js";
import type {
  MainJetEngineState,
  MainRocketPort,
  MainRocketState,
} from "../../../types/main.types.js";
import type { JetEngineTweenProps } from "../../../types/object.types.js";
import { Helpers } from "../../../utils/Helpers.js";
import { CONTACT_DEFAULT_SCENE_STATE } from "../scene/contact.scene.js";

export class ContactSceneRig {
  createDefaultValue(): ContactSceneState {
    const d = CONTACT_DEFAULT_SCENE_STATE;
    return {
      camera: {
        position: { ...d.camera.position },
        target: { ...d.camera.target },
        fov: d.camera.fov,
      },
      light: {
        ...d.light,
        rig: {
          position: { ...d.light.rig.position },
          rotation: { ...d.light.rig.rotation },
          scale: { ...d.light.rig.scale },
          visible: d.light.rig.visible,
        },
      },
      earth: {
        position: { ...d.earth.position },
        rotation: { ...d.earth.rotation },
        scale: { ...d.earth.scale },
        visible: d.earth.visible,
      },
      rocket: {
        position: { ...d.rocket.position },
        rotation: { ...d.rocket.rotation },
        scale: { ...d.rocket.scale },
        visible: d.rocket.visible,
        flame: { ...d.rocket.flame },
      } as MainRocketState,
      jetEngine: {
        position: { ...d.jetEngine.position },
        rotation: { ...d.jetEngine.rotation },
        scale: { ...d.jetEngine.scale },
        visible: d.jetEngine.visible,
        intensity: d.jetEngine.intensity,
        length: d.jetEngine.length,
        nozzleRadius: d.jetEngine.nozzleRadius,
        nozzleGap: d.jetEngine.nozzleGap,
        noise: d.jetEngine.noise,
        bloom: d.jetEngine.bloom,
      },
      terrian: {
        position: { ...d.terrian.position },
        rotation: { ...d.terrian.rotation },
        scale: { ...d.terrian.scale },
        visible: d.terrian.visible,
      },
    };
  }

  compose(state: ContactSceneState): SceneFromState {
    return {
      camera: {
        position: { ...state.camera.position },
        fov: state.camera.fov,
      },
      cameraTarget: {
        position: { ...state.camera.target },
      },
      [earthId]: state.earth,
      [rocketId]: state.rocket,
      [jetEngineId]: {
        position: { ...state.jetEngine.position },
        rotation: { ...state.jetEngine.rotation },
        scale: { ...state.jetEngine.scale },
        visible: state.jetEngine.visible,
      },
      [terrianId]: state.terrian,
    } as unknown as SceneFromState;
  }

  apply(engine: Engine, state: ContactSceneState): void {
    engine.setState(this.compose(state));
    engine.getCamera().lookAt(engine.getCameraTarget().position);
    this._applyLight(engine, state.light);
    this._applyRocket(engine, state.rocket);
    this._applyJetEngine(engine, state.jetEngine);
  }

  read(engine: Engine): ContactSceneState {
    const camera = engine.getCamera();
    const target = engine.getCameraTarget();
    const defaults = CONTACT_DEFAULT_SCENE_STATE;
    return {
      camera: {
        position: {
          x: this._toFinite(camera.position.x, defaults.camera.position.x),
          y: this._toFinite(camera.position.y, defaults.camera.position.y),
          z: this._toFinite(camera.position.z, defaults.camera.position.z),
        },
        target: {
          x: this._toFinite(target.position.x, defaults.camera.target.x),
          y: this._toFinite(target.position.y, defaults.camera.target.y),
          z: this._toFinite(target.position.z, defaults.camera.target.z),
        },
        fov: this._toFinite(camera.fov, defaults.camera.fov),
      },
      light: this._readLight(engine),
      earth: this._readTransform(engine, earthId, defaults.earth),
      rocket: this._readRocket(engine),
      jetEngine: this._readJetEngine(engine),
      terrian: this._readTransform(engine, terrianId, defaults.terrian),
    };
  }

  readCamera(engine: Engine): ContactCameraTheatreValue {
    return {
      camera: this.read(engine).camera,
    };
  }

  readObjectValue(value: ContactSceneState): ContactSceneState {
    return {
      camera: {
        position: { ...value.camera.position },
        target: { ...value.camera.target },
        fov: value.camera.fov,
      },
      light: {
        ...value.light,
        rig: {
          position: { ...value.light.rig.position },
          rotation: { ...value.light.rig.rotation },
          scale: { ...value.light.rig.scale },
          visible: value.light.rig.visible,
        },
      },
      earth: {
        position: { ...value.earth.position },
        rotation: { ...value.earth.rotation },
        scale: { ...value.earth.scale },
        visible: value.earth.visible,
      },
      rocket: {
        position: { ...value.rocket.position },
        rotation: { ...value.rocket.rotation },
        scale: { ...value.rocket.scale },
        visible: value.rocket.visible,
        flame: { ...value.rocket.flame },
      } as MainRocketState,
      jetEngine: {
        position: { ...value.jetEngine.position },
        rotation: { ...value.jetEngine.rotation },
        scale: { ...value.jetEngine.scale },
        visible: value.jetEngine.visible,
        intensity: value.jetEngine.intensity,
        length: value.jetEngine.length,
        nozzleRadius: value.jetEngine.nozzleRadius,
        nozzleGap: value.jetEngine.nozzleGap,
        noise: value.jetEngine.noise,
        bloom: value.jetEngine.bloom,
      },
      terrian: {
        position: { ...value.terrian.position },
        rotation: { ...value.terrian.rotation },
        scale: { ...value.terrian.scale },
        visible: value.terrian.visible,
      },
    };
  }

  private _applyLight(
    engine: Engine,
    state: ContactSceneState["light"],
  ): void {
    const light = engine.getSceneObjectById(
      aboutLightsId,
    ) as ContactLightsPort | null;
    if (!light) return;
    light.setState(state);
  }

  private _applyRocket(engine: Engine, state: MainRocketState): void {
    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
    if (!rocket) return;
    rocket.setFlameState(state.flame);
  }

  private _applyJetEngine(engine: Engine, state: MainJetEngineState): void {
    const jet = engine.getSceneObjectById(jetEngineId) as SceneObject<
      JetEngineTweenProps
    > | null;
    if (!jet || typeof jet.setTimelineVars !== "function") return;
    const { position: _p, rotation: _r, scale: _s, ...rest } = state;
    jet.setTimelineVars(rest, "to");
  }

  private _readLight(engine: Engine): ContactSceneState["light"] {
    const light = engine.getSceneObjectById(
      aboutLightsId,
    ) as ContactLightsPort | null;
    if (!light) {
      const d = CONTACT_DEFAULT_SCENE_STATE.light;
      return {
        ...d,
        rig: {
          position: { ...d.rig.position },
          rotation: { ...d.rig.rotation },
          scale: { ...d.rig.scale },
          visible: d.rig.visible,
        },
      };
    }
    return light.getState();
  }

  private _readRocket(engine: Engine): MainRocketState {
    const transform = this._readTransform(
      engine,
      rocketId,
      CONTACT_DEFAULT_SCENE_STATE.rocket,
    );
    const defaults = CONTACT_DEFAULT_SCENE_STATE.rocket;
    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
    return {
      ...transform,
      flame: rocket?.getFlameState() ?? defaults.flame,
    } as MainRocketState;
  }

  private _readJetEngine(engine: Engine): MainJetEngineState {
    const transform = this._readTransform(
      engine,
      jetEngineId,
      CONTACT_DEFAULT_SCENE_STATE.jetEngine,
    );
    const defaults = CONTACT_DEFAULT_SCENE_STATE.jetEngine;
    const object = engine.getSceneObjectById(jetEngineId) as
      | { getRuntimeOptions?: () => Record<string, unknown> }
      | null;
    const runtime = object?.getRuntimeOptions?.() ?? {};
    return {
      ...transform,
      intensity: this._toFinite(runtime.intensity, defaults.intensity),
      length: this._toFinite(runtime.length, defaults.length),
      nozzleRadius: this._toFinite(runtime.nozzleRadius, defaults.nozzleRadius),
      nozzleGap: this._toFinite(runtime.nozzleGap, defaults.nozzleGap),
      noise: this._toFinite(runtime.noise, defaults.noise),
      bloom: this._toFinite(runtime.bloom, defaults.bloom),
    };
  }

  private _readTransform(
    engine: Engine,
    id: string,
    fallback: ContactTransformState,
  ): ContactTransformState {
    const target = engine.getObjectById(id) as THREE.Object3D | null;
    const rotation = Helpers.readRotationDeg(target);
    return {
      position: {
        x: this._toFinite(target?.position.x, fallback.position.x),
        y: this._toFinite(target?.position.y, fallback.position.y),
        z: this._toFinite(target?.position.z, fallback.position.z),
      },
      rotation: {
        x: this._toFinite(rotation.x, fallback.rotation.x),
        y: this._toFinite(rotation.y, fallback.rotation.y),
        z: this._toFinite(rotation.z, fallback.rotation.z),
      },
      scale: {
        x: this._toFinite(target?.scale.x, fallback.scale.x),
        y: this._toFinite(target?.scale.y, fallback.scale.y),
        z: this._toFinite(target?.scale.z, fallback.scale.z),
      },
      visible: target?.visible ?? fallback.visible,
    };
  }

  private _toFinite(value: unknown, fallback: number): number {
    if (typeof value !== "number") return fallback;
    if (!Number.isFinite(value)) return fallback;
    return value;
  }
}

import * as THREE from "three";
import { getDefaultThreeConfig } from "../../../config/base.config.js";
import { ABOUT_LIGHT_STATE_DEFAULTS } from "../../../config/scene-light.config.js";
import {
  aboutBackground,
  aboutLights,
  earth,
  jetEngine,
  rocket,
  terrian,
} from "../../../core/setup.js";
import type { PageThreeConfig } from "../../../types/core.types.js";
import type {
  ContactInitialState,
  ContactPageConfig,
  ContactSceneState,
} from "../../../types/contact.types.js";
import type { MainJetEngineState, MainRocketState } from "../../../types/main.types.js";
import { runIntroDomTimeline } from "../../../runtime/IntroLoadingRuntime.js";
import { resolveContactAuthorMode } from "../theatre/ContactTheatreConfig.js";

const CONTACT_IS_AUTHOR_MODE = resolveContactAuthorMode();

const defaultThree = getDefaultThreeConfig();

export const CONTACT_DEFAULT_SCENE_STATE: ContactSceneState = {
