22	
23	const ZERO_VEC3: SceneVec3 = { x: 0, y: 0, z: 0 };
24	const UNIT_VEC3: SceneVec3 = { x: 1, y: 1, z: 1 };
25	const DEFAULT_MAIN_BLOOM_STATE: MainBloomState = {
26	  strength: 3.35,
27	  radius: 0.39,
28	  threshold: 0.83,
29	  compositeStrength: 1,
