40	
41	function cloneVec3(vector: SceneVec3): SceneVec3 {
42	  return { x: vector.x, y: vector.y, z: vector.z };
43	}
44	
45	function cloneTransformState(state: MainTransformState): MainTransformState {
46	  return {
47	    position: cloneVec3(state.position),
48	    rotation: cloneVec3(state.rotation),
49	    scale: cloneVec3(state.scale),
50	    visible: state.visible,
51	  };
52	}
53	
54	export function cloneRocketFlameState(
55	  state: MainRocketFlameState,
56	): MainRocketFlameState {
57	  return {
58	    visible: state.visible,
59	    offset: cloneVec3(state.offset),
60	    rotation: cloneVec3(state.rotation),
61	    scale: cloneVec3(state.scale),
62	    opacity: state.opacity,
63	    renderOrder: state.renderOrder,
64	    speed: state.speed,
65	    wave: state.wave,
66	  };
67	}
68	
69	export function cloneRocketState(state: MainRocketState): MainRocketState {
70	  return {
71	    position: cloneVec3(state.position),
72	    rotation: cloneVec3(state.rotation),
73	    scale: cloneVec3(state.scale),
74	    visible: state.visible,
75	    flame: cloneRocketFlameState(state.flame),
76	  };
77	}
78	
79	function cloneSceneLightsState(
80	  state: MainSceneLightsState,
81	): MainSceneLightsState {
82	  return {
83	    visible: state.visible,
84	    intensity: state.intensity,
85	    flightProgress: state.flightProgress,
86	    groundLight: state.groundLight,
87	    rocketFillLight: state.rocketFillLight,
88	    rocketRimLightLeft: state.rocketRimLightLeft,
89	    rocketRimLightRight: state.rocketRimLightRight,
90	    ground: cloneTransformState(state.ground),
91	  };
92	}
93	
94	function cloneBackgroundState(state: MainBackgroundState): MainBackgroundState {
95	  return {
96	    position: cloneVec3(state.position),
97	    rotation: cloneVec3(state.rotation),
98	    scale: cloneVec3(state.scale),
99	    visible: state.visible,
100	    exposure: state.exposure,
101	    look: cloneBackgroundLookState(state.look),
102	  };
103	}
104	
105	function cloneBackgroundLookState(
106	  state: MainBackgroundLookState,
107	): MainBackgroundLookState {
108	  return { ...state };
109	}
110	
111	function cloneCloudState(
112	  state: MainCloudState,
113	): MainCloudState {
114	  return {
115	    position: cloneVec3(state.position),
116	    rotation: cloneVec3(state.rotation),
117	    scale: cloneVec3(state.scale),
118	    visible: state.visible,
119	    chapter: state.chapter,
120	    transition: state.transition,
121	  };
122	}
123	
124	function cloneBloomState(state: MainBloomState): MainBloomState {
125	  return { ...state };
126	}
127	
128	function cloneVignetteState(state: MainVignetteState): MainVignetteState {
129	  return { ...state };
130	}
131	
132	function clonePostProcessingState(
133	  state: MainPostProcessingState,
134	): MainPostProcessingState {
135	  return {
136	    bloom: cloneBloomState(state.bloom),
137	    vignette: cloneVignetteState(state.vignette),
138	    exposure: state.exposure,
139	  };
140	}
141	
142	function cloneSceneShakeState(state: MainSceneShakeState): MainSceneShakeState {
143	  return {
144	    intensity: state.intensity,
145	  };
146	}
147	
148	function createTransformState(): MainTransformState {
149	  return {
150	    position: cloneVec3(ZERO_VEC3),
151	    rotation: cloneVec3(ZERO_VEC3),
152	    scale: cloneVec3(UNIT_VEC3),
153	    visible: false,
154	  };
155	}
156	
157	function createWindowStateFromConfig(): MainTransformState {
158	  return createTransformState();
159	}
160	
161	function createRocketFlameStateFromConfig(): MainRocketFlameState {
162	  const flame = OBJECT_CONFIG.rocket?.flame;
163	  return {
164	    visible: flame?.visible ?? true,
165	    offset: {
166	      x: typeof flame?.offset?.x === "number" ? flame.offset.x : 0,
167	      y: typeof flame?.offset?.y === "number" ? flame.offset.y : 0,
168	      z: typeof flame?.offset?.z === "number" ? flame.offset.z : 0,
169	    },
170	    rotation: {
171	      x: typeof flame?.rotation?.x === "number" ? flame.rotation.x : 0,
172	      y: typeof flame?.rotation?.y === "number" ? flame.rotation.y : 0,
173	      z: typeof flame?.rotation?.z === "number" ? flame.rotation.z : 0,
174	    },
175	    scale: {
176	      x: typeof flame?.scale?.x === "number" ? flame.scale.x : 1,
177	      y: typeof flame?.scale?.y === "number" ? flame.scale.y : 1,
178	      z: typeof flame?.scale?.z === "number" ? flame.scale.z : 1,
179	    },
180	    opacity: typeof flame?.opacity === "number" ? flame.opacity : 1,
181	    renderOrder:
182	      typeof flame?.renderOrder === "number" ? flame.renderOrder : 0,
183	    speed: typeof flame?.speed === "number" ? flame.speed : 2,
184	    wave: typeof flame?.wave === "number" ? flame.wave : 1.2,
185	  };
186	}
187	
188	function createGravityBallsStateFromConfig(): MainGravityBallsState {
189	  const gc = OBJECT_CONFIG.gravityBalls;
190	  const num = (v: unknown, fallback: number): number =>
191	    typeof v === "number" && Number.isFinite(v) ? v : fallback;
192	  return {
193	    visible: gc?.visible ?? true,
194	    dotsPerInterval: num(gc?.dotsPerInterval, 3),
195	    physicsScale: num(gc?.physicsScale, 0.006),
196	    maxGravityBoost: num(gc?.maxGravityBoost, 3.0),
197	  };
198	}
199	
200	export function cloneGravityBallsState(
201	  state: MainGravityBallsState,
202	): MainGravityBallsState {
203	  return {
204	    visible: state.visible,
205	    dotsPerInterval: state.dotsPerInterval,
206	    physicsScale: state.physicsScale,
207	    maxGravityBoost: state.maxGravityBoost,
208	  };
209	}
210	
211	export function mergeGravityBallsState(
212	  target: MainGravityBallsState,
213	  source?: Partial<MainGravityBallsState> | null,
214	): MainGravityBallsState {
215	  if (!source) return cloneGravityBallsState(target);
216	  const num = (s: number | undefined, t: number): number =>
217	    typeof s === "number" && Number.isFinite(s) ? s : t;
218	  return {
219	    visible: typeof source.visible === "boolean" ? source.visible : target.visible,
220	    dotsPerInterval: num(source.dotsPerInterval, target.dotsPerInterval),
221	    physicsScale: num(source.physicsScale, target.physicsScale),
222	    maxGravityBoost: num(source.maxGravityBoost, target.maxGravityBoost),
223	  };
224	}
225	
226	function createJetEngineStateFromConfig(): MainJetEngineState {
227	  const jc = OBJECT_CONFIG.jetEngine;
228	  const off = jc?.offset;
229	  const objectRotation = jc?.rotation;
230	  const objectScale = jc?.scale;
231	  const num = (v: unknown, fallback: number): number =>
232	    typeof v === "number" && Number.isFinite(v) ? v : fallback;
233	  return {
234	    position: {
235	      x: num(off?.x, 0),
236	      y: num(off?.y, 0),
237	      z: num(off?.z, 0),
238	    },
239	    rotation: {
240	      x: num(objectRotation?.x, 0),
241	      y: num(objectRotation?.y, 0),
242	      z: num(objectRotation?.z, 0),
243	    },
244	    scale: {
245	      x: num(objectScale?.x, 1),
246	      y: num(objectScale?.y, 1),
247	      z: num(objectScale?.z, 1),
248	    },
249	    visible: jc?.visible ?? true,
250	    intensity: num(jc?.intensity, 0.78),
251	    length: num(jc?.length, 2.4),
